/** Org record decorated with the caller's own membership, for the shell UI. */
export interface OrganizationSummary {
  readonly organization: Organization;
  readonly usage: OrganizationUsage;
  readonly memberCount: number;
  readonly projectCount: number;
}

export type OwnershipHandoverStatus =
  | "pending"
  | "accepted"
  | "declined"
  | "canceled"
  | "expired";

/**
 * An open (or resolved) offer to hand the recorded owner's seat to another
 * member. `expiresAt` is always exactly seven days after `createdAt`; a
 * `"pending"` offer whose `expiresAt` has passed reads back as `"expired"`
 * rather than being flipped by a background job.
 */
export interface OwnershipHandover {
  readonly id: string;
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly status: OwnershipHandoverStatus;
