/**
 * Ownership-handover offers. At most one row per org is left `"pending"` at a
 * time — enforced by the service layer, not a DB constraint.
 */
import { and, desc, eq } from "drizzle-orm";
import { addDays } from "@/lib/date";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { OwnershipHandover } from "@/types/organization";

const HANDOVER_EXPIRY_DAYS = 7;

export async function insertOwnershipHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = addDays(stamp, HANDOVER_EXPIRY_DAYS);

  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      resolvedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/**
 * The most recent `"pending"` row for the org, if any. The mapper reads it
 * back as `"expired"` once `expiresAt` has passed, so callers check
 * `handover.status === "pending"` to decide whether it is actually open.
 */
export async function findOpenHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .get();

  return row ? toOwnershipHandover(row) : null;
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: "accepted" | "declined" | "canceled",
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, id),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();

  if (!row) {
    throw new Error(`Ownership handover ${id} not found or already resolved`);
  }
  return toOwnershipHandover(row);
}

