export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

/**
 * Holding the owner role is not enough: only the org's recorded `ownerId` may
 * offer or withdraw a handover. Both the role-rank refusal (from `assertCan`)
 * and this one surface as `PermissionDeniedError`.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  assertCan(actor, "org:manage_ownership", orgResource(org.id));

  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:manage_ownership", {
      action: "org:manage_ownership",
      resourceKind: "organization",
      allowed: false,
      reason: "denied_by_role",
    });
  }
}

/**
 * As the recorded owner, offer the workspace to another active member. Only
 * one offer may be open per org at a time; a lapsed offer does not block a
 * new one.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const existing = await handoverRepo.findOpenHandover(orgId);
  if (existing && existing.status === "pending") {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await handoverRepo.insertOwnershipHandover(
    orgId,
    actor.userId,
    toUserId,
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered workspace ownership",
    body: `${org.name}'s owner offered you ownership of this workspace`,
    href: "/settings",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * As the offered member — whatever their current role — accept the handover.
 * They become the recorded owner and the owner role; the previous owner steps
 * down to admin if they still hold the owner role at that moment.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const handover = await handoverRepo.findOpenHandover(orgId);
  if (!handover || handover.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (handover.status !== "pending") {
    throw new OwnershipHandoverError("expired");
  }

  const toMember = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );

  if (toMember.role !== "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, toMember.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: toMember.role,
      to: "owner",
    });
  }

  const fromMember = await memberRepo.findMember(orgId, handover.fromUserId);
  if (fromMember && fromMember.role === "owner") {
    const updated = await memberRepo.updateMemberRole(orgId, fromMember.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: updated.id,
      from: "owner",
      to: "admin",
    });
  }

  const updatedOrg = await orgRepo.updateOwnerId(orgId, actor.userId);

  await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: actor.userId,
  });

  return updatedOrg;
}

/** As the offered member, decline — nothing is pending afterwards. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const handover = await handoverRepo.findOpenHandover(orgId);
  if (!handover || handover.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (handover.status !== "pending") {
    throw new OwnershipHandoverError("expired");
  }

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** As the offering owner, withdraw the offer while it is still open. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const handover = await handoverRepo.findOpenHandover(orgId);
  if (!handover || handover.status !== "pending") {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

/** Any member may see whether an offer is open and to whom; a lapsed offer is not shown. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const handover = await handoverRepo.findOpenHandover(orgId);
  if (!handover || handover.status !== "pending") return null;
  return handover;
}

/**
 * If either side of an open offer leaves the workspace, the offer is
 * withdrawn automatically rather than left dangling against a departed user.
 */
let ownershipHandoverListenersRegistered = false;

function registerOwnershipHandoverListeners(): void {
  if (ownershipHandoverListenersRegistered) return;
  ownershipHandoverListenersRegistered = true;

  subscribe("member.removed", async (payload) => {
    const handover = await handoverRepo.findOpenHandover(payload.orgId);
    if (!handover || handover.status !== "pending") return;

    if (handover.fromUserId === payload.userId || handover.toUserId === payload.userId) {
      await handoverRepo.resolveHandover(
        payload.orgId,
        handover.id,
        "canceled",
        toIsoTimestamp(new Date()),
      );
    }
  });
}

registerOwnershipHandoverListeners();

